  titleAi.addEventListener('click',()=>generateMetadataField('title'));descriptionAi.addEventListener('click',()=>generateMetadataField('description'));cancelMetadata.addEventListener('click',()=>stop());
  window.addEventListener('studio-api-settings-change',()=>{if(busy.startsWith('metadata-'))stop('AI API 설정이 바뀌어 작성을 취소했어요. 기존 입력은 유지돼요.');});
  file.input.addEventListener('change',()=>{try{const picked=file.input.files?.[0];if(!picked)return;validateYouTubeVideoFile(picked);clearThumbnailSelection();disarmQueue();selectedFile={...scope(),blob:picked,name:picked.name};error.textContent='';renderStatus();}catch(cause){selectedFile=null;showError(cause);renderStatus();}});
  saveClient.addEventListener('click',()=>{try{if(busy)return;placeStatus(true);const value=normalizeYouTubeClientId(clientId.input.value);client.saveClientId(value);clientId.input.value=value;setup.open=!value;error.textContent='';status.textContent=value?'클라이언트 ID를 저장했어요. Google 계정으로 YouTube를 연결하세요.':'클라이언트 ID와 연결을 지웠어요.';render();}catch(cause){showError(cause);}});
  async function clearStoredHistory({disconnectAccount=false}={}){if(busy||!canMutate())return;placeStatus(disconnectAccount);const target=scope(),seq=++serial;busy='history';const task=operation.start(disconnectAccount?'YouTube 연결과 이 앱에 저장된 업로드 기록을 지우고 있어요.':'모든 작업 탭과 보관함의 업로드 기록을 지우고 있어요.');activeOperation=task;error.textContent='';renderStatus();try{if(disconnectAccount){client.disconnect();autoQueue=null;pausedOwner=null;pendingThumbnail=null;pausedThumbnail=null;}if(typeof api.clearYouTubeStoredHistory!=='function')throw new Error('업로드 기록을 지울 준비가 되지 않았어요. 새로고침한 뒤 다시 시도하세요.');await api.clearYouTubeStoredHistory();if(seq!==serial||!owns(target))return;status.textContent=disconnectAccount?'YouTube 연결과 이 앱의 업로드 기록을 지웠어요. YouTube에 올린 실제 영상은 유지돼요.':'이 앱의 모든 업로드 기록을 지웠어요. 작성한 업로드 내용과 실제 YouTube 영상은 유지돼요.';task.finish(status.textContent);}catch(cause){if(seq===serial&&owns(target)){showError(cause);task.fail(cause.message);}}finally{if(seq===serial){busy='';activeOperation=null;historyFingerprint='';render();}}}
  cancelConnection.addEventListener('click',()=>stop('Google 채널 연결을 취소했어요.'));connect.addEventListener('click',connectChannel);disconnect.addEventListener('click',()=>clearStoredHistory({disconnectAccount:true}));clearHistory.addEventListener('click',()=>clearStoredHistory());
  saveDraft.addEventListener('click',async()=>{try{placeStatus();flush({strict:true});await api.persist?.();status.textContent='업로드할 제목·설명·공개 상태를 저장했어요.';}catch(cause){showError(cause);}});
  function importPublishingDraft(){try{const value=publishingToYouTubeMetadata(api.getProject());title.input.value=value.title;description.input.value=value.description;tags.input.value=value.tags.join(', ');dirty=true;updateCounts();flush({strict:false});disarmQueue();error.textContent='';placeStatus();status.textContent='게시 자료의 제목·내용 요약·태그를 가져왔어요. 공개 상태와 내용을 확인하세요.';renderStatus();}catch(cause){showError(cause);}}
  importPublishing.addEventListener('click',importPublishingDraft);
